set-variable.value:
@{
                var root = context.Request.Body.As<JObject>(preserveContent: true);
                var newestUserSlice = "";
                var sysSlice = "";
                var toolSlice = "";
                var truncated = false;
                return new JObject(
                    new JProperty("userPrompt", newestUserSlice),
                    new JProperty("documents", new JArray(toolSlice)),
                    new JProperty("analyzeText", sysSlice + newestUserSlice + toolSlice),
                    new JProperty("truncated", truncated),
                    new JProperty("emptyTextSlice", String.IsNullOrEmpty(sysSlice + newestUserSlice + toolSlice))
                ).ToString(Newtonsoft.Json.Formatting.None);
            }

@{
                var threshold = (int)context.Variables["contentSafetyThreshold"];
                var shield = context.Variables.ContainsKey("contentSafetyShieldResponse") ? (IResponse)context.Variables["contentSafetyShieldResponse"] : null;
                var analyze = context.Variables.ContainsKey("contentSafetyAnalyzeResponse") ? (IResponse)context.Variables["contentSafetyAnalyzeResponse"] : null;
                if (shield == null || analyze == null || shield.StatusCode < 200 || shield.StatusCode > 299 || analyze.StatusCode < 200 || analyze.StatusCode > 299) { return "unavailable"; }
                return "pass";
            }
